public class InstantiatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            Object obj = Instantiator.create("Widget");
            check("create(\"Widget\") returns something", true, obj != null);
            check("create(\"Widget\") is a Widget", true, obj instanceof Widget);
            check("the Widget's name was set", "widget",
                    (obj instanceof Widget) ? ((Widget) obj).getName() : null);
            Object again = Instantiator.create("Widget");
            check("each call builds a fresh instance", true, again != null && again != obj);
            Object sb = Instantiator.create("java.lang.StringBuilder");
            check("create(\"java.lang.StringBuilder\") is a StringBuilder", true,
                    sb instanceof StringBuilder);
            check("the StringBuilder starts empty", 0,
                    (sb instanceof StringBuilder) ? ((StringBuilder) sb).length() : null);
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

