class Widget {
    private final String name;

    Widget() {
        this.name = "widget";
    }

    String getName() {
        return name;
    }
}

public class Instantiator {

    public static Object create(String className) throws Exception {
        Class<?> c = Class.forName(className);
        return c.getDeclaredConstructor().newInstance();
    }
}
